-- PolicyPeek 2026-10-28 full-catalog-audit data update. PREPARED ONLY, NOT RUN. Run AFTER 2026-10-28-recheck.
-- Needs Elliot's own approval before Jump runs it. Generated by tools/gen_apply.py from frontend/data/tools.json.
-- Source: deliverables/research/full-catalog-audit-2026-10-28.md, plus Jump's manual browser readings of 28 Oct
-- (ChatGPT, Midjourney, Otter). Atomic: D1 runs a --file as one batch; a failed GUARD/ASSERT (json() on invalid
-- text) rolls back every statement.

-- 1. BEFORE SNAPSHOT (tools/gen_rollback.mjs rebuilds every row and the held tools' changelog rows from these)
SELECT 'before_snapshot' AS snapshot, * FROM tools WHERE domain IN ('bolt.new', 'copy.ai', 'cursor.com', 'github.com', 'grammarly.com', 'heygen.com', 'jasper.ai', 'jetbrains.com', 'kimi.com', 'midjourney.com', 'mistral.ai', 'openai.com', 'otter.ai', 'replit.com', 'runway.com', 'stability.ai', 'windsurf.com', 'zoom.com') ORDER BY domain;
SELECT 'before_changelog' AS snapshot, c.* FROM compliance_changelog c JOIN tools t ON t.id = c.tool_id WHERE t.domain IN ('copy.ai', 'jasper.ai', 'replit.com', 'runway.com', 'stability.ai', 'cursor.com', 'windsurf.com', 'midjourney.com', 'otter.ai') ORDER BY c.id;
SELECT 'before_counts' AS snapshot, compliance_status, COUNT(*) AS n FROM tools GROUP BY compliance_status ORDER BY compliance_status;
SELECT 'queued_rechecks' AS snapshot, id, domain, status, created_at FROM pending_checks WHERE status IN ('pending','extracted') AND domain IN ('bolt.new', 'copy.ai', 'cursor.com', 'github.com', 'grammarly.com', 'heygen.com', 'jasper.ai', 'jetbrains.com', 'kimi.com', 'midjourney.com', 'mistral.ai', 'openai.com', 'otter.ai', 'replit.com', 'runway.com', 'stability.ai', 'windsurf.com', 'zoom.com');

