-- 3. HOLDS: unpublish (held tools are never in `tools`). Changelog rows are FK-bound, so they go first.
-- copy.ai, jasper.ai, replit.com, runway.com, stability.ai: policy silent on training -> held, not unrated.
-- cursor.com: free-tier Privacy Mode default missing/contradictory. windsurf.com: sources redirect off-domain.
-- midjourney.com: policy unclear (docs.midjourney.com 403). otter.ai: opt-out default, plans and coverage of
--   de-identified training not stated (Jump's reading of help.otter.ai articles 25352082563863 and 13352505516695).
DELETE FROM compliance_changelog WHERE tool_id IN (SELECT id FROM tools WHERE domain IN ('copy.ai', 'jasper.ai', 'replit.com', 'runway.com', 'stability.ai', 'cursor.com', 'windsurf.com', 'midjourney.com', 'otter.ai'));
DELETE FROM tools WHERE domain IN ('copy.ai', 'jasper.ai', 'replit.com', 'runway.com', 'stability.ai', 'cursor.com', 'windsurf.com', 'midjourney.com', 'otter.ai');

